  const steps: [string, number][] = [["Leave home", dep - (sec + tr) * 6e4], ["Arrive at airport", dep - sec * 6e4], ["Bag drop closes (typical)", dep - 60 * 6e4], ["Gate usually opens", dep - 45 * 6e4], ["Boarding (typical)", dep - 35 * 6e4], ["Gate closes (typical)", dep - 20 * 6e4], ["Departure", dep]];
  if (f.arr.scheduled) steps.push(["Arrival", +new Date(f.arr.estimated || f.arr.scheduled)]);
