export function ToolsHub({ open }: { open?: string }) { const [sel, ss] = useState<string | null>(open || null); const [q, sq] = useState(""); const t = TOOLS.find(x => x.id === sel);
  if (t) return <div className="t-tool"><button className="btn" onClick={() => ss(null)}>‹ All tools</button><h2 className="mt8">{t.n}</h2><div className="muted sm">{t.d}</div><div className="mt8"><t.el /></div></div>;
  const L = TOOLS.filter(x => (x.n + x.d + x.m).toLowerCase().includes(q.toLowerCase())); const mods = [...new Set(L.map(x => x.m))];
  return <div><input className="field" placeholder={`Search ${TOOLS.length} tools`} value={q} onChange={e => sq(e.target.value)} />{mods.map(m => <div key={m} className="mt8"><div className="t-lab">{m}</div>{L.filter(x => x.m === m).map(x => <button key={x.id} className="t-item" onClick={() => ss(x.id)}><b className="sm">{x.n}</b><span className="muted xs">{x.d}</span></button>)}</div>)}</div>; }
export function FeatureList() { const mods = [...new Set(TOOLS.map(x => x.m))];
  return <div><div className="t-big">{TOOLS.length + BOARD_FEATURES.length + NEW_V7.length + NEW_V8.length + NEW_V9.length + NEW_V10.length + NEW_V11.length + NEW_V12.length + NEW_V13.length + NEW_V14.length} features</div><div className="muted sm">{NEW_V14.length} new in this update, {NEW_V7.length} in the previous one, {TOOLS.length} tools and {BOARD_FEATURES.length} board improvements. Each one uses live data, your own saved flights, or a stated formula. Nothing is invented.</div>
    <div className="t-lab mt8">New in this update ({NEW_V14.length})</div>{NEW_V14.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v13 ({NEW_V13.length})</div>{NEW_V13.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v12 ({NEW_V12.length})</div>{NEW_V12.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v11 ({NEW_V11.length})</div>{NEW_V11.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v10 ({NEW_V10.length})</div>{NEW_V10.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v9 ({NEW_V9.length})</div>{NEW_V9.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">v8 ({NEW_V8.length})</div>{NEW_V8.map(f => <div key={f} className="t-out sm">{f}</div>)}<div className="t-lab mt8">Previous update ({NEW_V7.length})</div>{NEW_V7.map(f => <div key={f} className="t-out sm">{f}</div>)}
    <div className="t-lab mt8">Boards ({BOARD_FEATURES.length})</div>{BOARD_FEATURES.map(f => <div key={f} className="t-out sm">{f}</div>)}
    {mods.map(m => { const l = TOOLS.filter(x => x.m === m); return <div key={m}><div className="t-lab mt8">{m} ({l.length})</div>{l.map(x => <div key={x.id} className="t-out sm"><b>{x.n}</b> <span className="muted">{x.d}</span></div>)}</div>; })}
    <div className="t-lab mt8">Not included, and why</div>{GAPS.map(g => <div key={g} className="t-out sm muted">{g}</div>)}</div>; }
